2	//   "When I open a project I want to see its invoices. Show me what they add up to. Let me add a
3	//    new invoice for an amount."
4	//
5	// Opening a project (project-open-<id> from the projects list) lands on that project's detail page.
6	// The detail page lists THAT project's invoices, each showing its amount, and shows what they add
7	// up to (project-invoices-total). A new invoice is added by giving an amount; once added it joins
8	// the same invoices list, the total grows by that amount, and both survive a fresh load.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
11	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
12	// `invoices` honours { id, amount, projectId }.
13	import { test, expect, type Page, type Locator } from '@playwright/test';
14	import { resetAndSeed } from '../support/seed';
15	
16	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
17	
18	// A money value may be rendered with a currency symbol, grouping or decimals ($1,200.00) or bare
19	// (1200). Assert the amount it carries is PRESENT, so the test binds to "what they add up to"
20	// rather than to one presentation. The digits used below are chosen so no amount or total is a
21	// substring of another.
22	const digits = (n: number) => String(n);
23	
24	async function expectAmount(cell: Locator, n: number): Promise<void> {
25	  await expect(cell).toContainText(digits(n));
26	}
