29	  test('opening a project from the list lands on its detail page', async ({ page }) => {
30	    await resetAndSeed({
31	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
32	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
33	      invoices: [],
34	    });
35	
36	    await page.goto('/projects');
37	    await expect(page.getByTestId('project-row-1')).toBeVisible();
38	
39	    // Opening the project is a navigation, not a flag: following it lands on that project's own
40	    // detail page.
41	    const open = page.getByTestId('project-open-1');
42	    await expect(open).toBeVisible();
43	    await open.click();
44	
45	    await expect(page).toHaveURL(/\/projects\/1$/);
46	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
47	  });
48	
49	  test('the detail page lists the project invoices with their amounts and what they add up to', async ({
50	    page,
51	  }) => {
52	    await resetAndSeed({
53	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
54	      projects: [
55	        { id: 1, name: 'Website Redesign', clientId: 1 },
56	        { id: 2, name: 'Mobile App', clientId: 1 },
57	      ],
58	      invoices: [
59	        { id: 1, amount: 100, projectId: 1 },
60	        { id: 2, amount: 250, projectId: 1 },
61	        { id: 3, amount: 50, projectId: 1 },
62	        // An invoice on a DIFFERENT project must not show here, nor count toward this total.
63	        { id: 4, amount: 999, projectId: 2 },
64	      ],
65	    });
66	
67	    await page.goto('/projects/1');
68	
69	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
70	    await expect(page.getByTestId('project-invoices-table')).toBeVisible();
71	
72	    // Only this project's three invoices are shown, each carrying its own amount.
73	    await expect(invoiceRows(page)).toHaveCount(3);
74	    await expectAmount(page.getByTestId('invoice-row-1').getByTestId('invoice-amount'), 100);
75	    await expectAmount(page.getByTestId('invoice-row-2').getByTestId('invoice-amount'), 250);
76	    await expectAmount(page.getByTestId('invoice-row-3').getByTestId('invoice-amount'), 50);
